export function registerTools(a){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[
 {name:'orbit_read_session',title:'Read DJ session',description:'Read deck, mixer, library and layout state. Does not start audio or request device access.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {decks:a.s.decks.map((d,i)=>({deck:i,trackId:d.trackId,name:a.getTrack(i)?.name||null,position:a.position(i),playing:d.playing,bpm:a.getTrack(i)?.bpm,rate:d.rate})),mixer:{...a.s.mixer},layout:a.s.layout,tracks:[...a.tracks.values()].map(t=>({id:t.id,name:t.name,artist:t.artist,bpm:t.bpm,duration:t.duration}))};}},
 {name:'orbit_set_layout_preset',title:'Set workspace layout',description:'Apply a 2-deck, 4-deck or library-focused layout and save it on this device. Does not change audio playback.',inputSchema:{type:'object',properties:{preset:{type:'string',enum:['two','four','focus']}},required:['preset'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['two','four','focus'].includes(input.preset)||Object.keys(input).some(k=>k!=='preset'))throw new Error('preset must be two, four or focus');a.layout.setPreset(input.preset);a.render();return {preset:a.s.preset,visiblePanels:Object.entries(a.s.layout).filter(([,p])=>p.visible).map(([id])=>id)};}},
 {name:'orbit_load_decks',title:'Load local tracks into stopped decks',description:'Load existing library tracks into unlocked, stopped decks. Audio may require the user to enable audio first. Never starts playback.',inputSchema:{type:'object',properties:{loads:{type:'array',minItems:1,maxItems:4,items:{type:'object',properties:{deck:{type:'integer',minimum:0,maximum:3},trackId:{type:'string'}},required:['deck','trackId'],additionalProperties:false}}},required:['loads'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||!Array.isArray(input.loads)||!input.loads.length||input.loads.length>4)throw new Error('Provide 1–4 loads');const seen=new Set();for(const l of input.loads){if(!Number.isInteger(l.deck)||l.deck<0||l.deck>3||seen.has(l.deck)||!a.tracks.has(l.trackId))throw new Error('Invalid deck or track');if(a.s.decks[l.deck].playing||a.s.decks[l.deck].locked)throw new Error('Deck is playing or locked');seen.add(l.deck);}if(a.engine.context?.state!=='running')throw new Error('Enable audio with the visible Audio button first');for(const l of input.loads)await a.loadDeck(l.deck,l.trackId);return {loaded:input.loads.map(l=>({deck:l.deck,trackId:a.s.decks[l.deck].trackId,playing:false}))};}}
 ];for(const t of tools)try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
